<?php
namespace App\Http\Controllers;
use App\Models\Invoice; use App\Models\Client; use Illuminate\Http\Request; use Illuminate\Validation\Rule; use Illuminate\View\View; use Illuminate\Http\RedirectResponse;
class InvoiceController extends Controller {
public function index(Request $r):View{return view('invoices.index',['invoices'=>$r->user()->invoices()->with('client')->latest()->paginate(12)]);} public function create(Request $r):View{return view('invoices.form',['clients'=>$r->user()->clients()->orderBy('name')->get()]);}
public function store(Request $r):RedirectResponse{$data=$r->validate(['number'=>'required|string|max:40|unique:invoices,number','client_id'=>['required',Rule::exists('clients','id')->where('user_id',$r->user()->id)],'issue_date'=>'required|date','due_date'=>'nullable|date|after_or_equal:issue_date','amount'=>'required|numeric|min:0','currency'=>'required|string|size:3','status'=>'required|in:draft,sent,paid,overdue']);$invoice=$r->user()->invoices()->create($data);return redirect()->route('invoices.show',$invoice)->with('success','Invoice created.');}
public function show(Request $r,Invoice $invoice):View{$this->own($r,$invoice);return view('invoices.show',['invoice'=>$invoice->load('client')]);} public function edit(Request $r,Invoice $invoice):View{$this->own($r,$invoice);return view('invoices.form',['invoice'=>$invoice,'clients'=>$r->user()->clients()->orderBy('name')->get()]);}
public function update(Request $r,Invoice $invoice):RedirectResponse{$this->own($r,$invoice);$data=$r->validate(['number'=>'sometimes|required|string|max:40|unique:invoices,number,'.$invoice->id,'client_id'=>['sometimes','required',Rule::exists('clients','id')->where('user_id',$r->user()->id)],'issue_date'=>'sometimes|required|date','due_date'=>'nullable|date|after_or_equal:issue_date','amount'=>'sometimes|required|numeric|min:0','currency'=>'sometimes|required|string|size:3','status'=>'sometimes|required|in:draft,sent,paid,overdue']);$invoice->update($data);return redirect()->route('invoices.show',$invoice)->with('success','Invoice updated.');} public function destroy(Request $r,Invoice $invoice):RedirectResponse{$this->own($r,$invoice);$invoice->delete();return redirect()->route('invoices.index')->with('success','Invoice deleted.');}private function own(Request $r,Invoice $invoice):void{abort_unless($invoice->user_id===$r->user()->id,404);}}
